namespace Cdns.Application.Interfaces;

/// <summary>
/// Static helpers for converting between UTC and Asia/Colombo local time (UTC+05:30, no DST).
/// </summary>
/// <remarks>
/// ASYCUDA/Oracle DATE values are Colombo local time — use <see cref="FromColomboToUtc(DateTime?)"/>
/// when reading them into C#. Use <see cref="ToColombo(DateTime)"/> when deriving a Colombo
/// calendar day (year/month/day comparisons) from a stored UTC value. Values generated by our
/// own code should always use <c>DateTime.UtcNow</c> directly.
/// </remarks>
public static class SriLankaTime
{
    /// <summary>Asia/Colombo timezone (UTC+05:30, no DST).</summary>
    public static readonly TimeZoneInfo Zone =
        TimeZoneInfo.FindSystemTimeZoneById("Asia/Colombo");

    /// <summary>
    /// Converts a Colombo-local <see cref="DateTime"/> (from ASYCUDA/Oracle) to UTC.
    /// Returns <c>null</c> when <paramref name="local"/> is <c>null</c>.
    /// </summary>
    public static DateTime? FromColomboToUtc(DateTime? local)
    {
        if (local is null) return null;
        return TimeZoneInfo.ConvertTimeToUtc(
            DateTime.SpecifyKind(local.Value, DateTimeKind.Unspecified), Zone);
    }

    /// <summary>
    /// Converts a Colombo-local <see cref="DateTime"/> (from ASYCUDA/Oracle) to UTC.
    /// </summary>
    public static DateTime FromColomboToUtc(DateTime local) =>
        TimeZoneInfo.ConvertTimeToUtc(
            DateTime.SpecifyKind(local, DateTimeKind.Unspecified), Zone);

    /// <summary>
    /// Converts a UTC <see cref="DateTime"/> to Asia/Colombo local time.
    /// Use when deriving a Colombo calendar day (year/month/day comparisons) from a stored UTC value.
    /// </summary>
    public static DateTime ToColombo(DateTime utc) =>
        TimeZoneInfo.ConvertTimeFromUtc(
            DateTime.SpecifyKind(utc, DateTimeKind.Utc), Zone);
}
